// Did a refactor change any generated byte? Hashes (SHA-256) every file under games/*/disk, each game's
// walkthrough.json and walkPaths.json, and prints what was added, removed or changed against a saved list.
// Only reads: it never builds, so run the build first (in a worktree whose disks are real folders).
//   npm run check:same-bytes -- --save before.json            hash now, write the list
//   npm run check:same-bytes -- --compare before.json         hash now, print differences (exit 1 if any)
//   options: --game id,id  only those games;  --games-dir dir  (default ../games)
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { join, relative, resolve } from 'node:path';

export type Hashes = Record<string, string>;

function walk(dir: string, out: string[]): void {
  for (const name of readdirSync(dir).sort()) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) walk(p, out);
    else out.push(p);
  }
}

/** Hash of every disk file, walkthrough and walk path, keyed by path under the games folder. */
export function hashGames(gamesDir: string, only?: string[]): Hashes {
  const out: Hashes = {};
  for (const id of readdirSync(gamesDir).sort()) {
    const game = join(gamesDir, id);
    if (!statSync(game).isDirectory() || (only && !only.includes(id))) continue;
    const files: string[] = [];
    if (existsSync(join(game, 'disk'))) walk(join(game, 'disk'), files);
    for (const f of ['walkthrough.json', 'walkPaths.json']) if (existsSync(join(game, f))) files.push(join(game, f));
    for (const f of files) out[relative(gamesDir, f)] = createHash('sha256').update(readFileSync(f)).digest('hex');
  }
  return out;
}

/** Lines describing how `after` differs from `before` (empty when the bytes are the same). */
export function diffHashes(before: Hashes, after: Hashes): string[] {
  const lines: string[] = [];
  for (const k of Object.keys(before).sort()) {
    if (!(k in after)) lines.push(`removed  ${k}`);
    else if (before[k] !== after[k]) lines.push(`changed  ${k}`);
  }
  for (const k of Object.keys(after).sort()) if (!(k in before)) lines.push(`added    ${k}`);
  return lines;
}

function main(): void {
  const args = process.argv.slice(2);
  const val = (f: string): string | undefined => (args.includes(f) ? args[args.indexOf(f) + 1] : undefined);
  const gamesDir = resolve(val('--games-dir') ?? '../games');
  const only = val('--game')?.split(',');
  const save = val('--save');
  const compare = val('--compare');
  if (!save === !compare) {
    console.error('Give exactly one of --save <file> or --compare <file>.');
    process.exit(2);
  }
  const now = hashGames(gamesDir, only);
  if (save) {
    writeFileSync(save, JSON.stringify(now, null, 1) + '\n');
    console.log(`${Object.keys(now).length} files hashed into ${save}`);
    return;
  }
  const before = JSON.parse(readFileSync(compare!, 'utf8')) as Hashes;
  const scope = only ? Object.fromEntries(Object.entries(before).filter(([k]) => only.includes(k.split('/')[0]))) : before;
  const lines = diffHashes(scope, now);
  console.log(lines.length ? lines.join('\n') : `Same bytes: ${Object.keys(now).length} files.`);
  console.log(lines.length ? `\n${lines.length} difference(s).` : '');
  process.exit(lines.length ? 1 : 0);
}

if (!process.env.VITEST) main();
